# -*- coding: utf-8 --
import time
from os import path
from taf.rfrl.cbts.utilities import tl_config
from taf.rfrl.cbts.utilities import generic_utils
from taf.hw.fhgw.cli import cli as issh_cli
from taf.rfrl.cbts.parsers.parsers import get_pod_and_container_name
from robot.api import logger

LOG_HEAD = LOG_END = "*" * 8


class SSHConnExec(object):
    #: the object of taf.hw.fhgw.cli
    ssh_conn = issh_cli()

    def __init__(self):
        self.vdu_ssh_conn_store = []
        self.vcu_ssh_conn_store = []
        self.fhgw_ssh_conn_store = []

    def connect_to_vdu_cloud_hosting(self, using_tenant=False,
                                     prompt=None, keyfile='',
                                     timeout=150, width=200,
                                     alias='default',
                                     gnb_index=0, vdu_index=0):
        """
        connect to vdu cloud hosting.

        :param boolean using_tenant: connect to the cloud hosting by tenant or core
        :param str prompt: the terminal prompt after connected, default is None.
        :param str keyfile: key file path, default is empty.
        :param Union[int,str] timeout: (optional) Timeout for ssh connection setup, default is 150s.
        :param int width: width of ssh window (optional), default is 200.
        :param str alias: connection alias, default is 'default'.
        :param int gnb_index: gnb index in testline init file.
        :param int vdu_index: vdu index in testline init file.
        :return str: connection alias
        """
        vdu_cloud_hosting_credentials = tl_config.get_vdu_cloud_hosting_credentials(tenant_credentials=using_tenant,
                                                                                    gnb_index=gnb_index,
                                                                                    vdu_index=vdu_index)

        if prompt is None or prompt == "":
            myprompt = r"\[{}@\S+\s\S+\]\$".format(vdu_cloud_hosting_credentials['username'])
        else:
            myprompt = prompt

        self.ssh_conn.connect_to(ip=vdu_cloud_hosting_credentials['ip'],
                                 username=vdu_cloud_hosting_credentials['username'],
                                 password=vdu_cloud_hosting_credentials['password'],
                                 prompt=myprompt,
                                 timeout=timeout,
                                 width=width,
                                 alias=alias,
                                 keyfile=keyfile)
        self.vdu_ssh_conn_store.append(alias)
        return alias

    def disconnect_vdu_cloud_hosting(self, alias='default'):
        """
        disconnect the ssh connection from vdu cloud hosting.

        :param str alias: ssh connection alias.
        :return: None
        """
        try:
            self.ssh_conn.disconnect(alias=alias)
            self.vdu_ssh_conn_store.remove(alias)
        except Exception:
            logger.error(
                "{} SSH connection Already disconnected, no need to disconnect it once again {}".format(LOG_HEAD,
                                                                                                        LOG_END))

    def disconnect_all_vdu_cloud_hosting(self):
        self.ssh_conn.disconnect()

    def connect_to_vcu_cloud_hosting(self, using_tenant=False,
                                     prompt=None, keyfile='',
                                     timeout=150, width=200,
                                     alias='default', gnb_index=0):
        """
       connect to vcu cloud hosting.

       :param boolean using_tenant: connect to the cloud hosting by tenant or core
       :param str prompt: the terminal prompt after connected, default is \\[core@\\S+\\s\\S+\\]\\$|\\[cranuser\\d+@\\S+\\s+\\S+\\]\\$
       :param str keyfile: key file path, default is empty.
       :param Union[int,str] timeout: (optional) Timeout for ssh connection setup, default is 150s.
       :param int width: width of ssh window (optional), default is 200.
       :param str alias: connection alias, default is 'default'.
       :param int gnb_index: gnb index in testline init file.
       :param int vdu_index: vdu index in testline init file.
       :return str: connection alias
       """
        vcu_cloud_hosting_credentials = tl_config.get_vcu_cloud_hosting_credentials(tenant_credentials=using_tenant,
                                                                                    gnb_index=gnb_index)

        if prompt is None or prompt == "":
            myprompt = r"\[{}@\S+\s\S+\]\$".format(vcu_cloud_hosting_credentials['username'])
        else:
            myprompt = prompt

        self.ssh_conn.connect_to(ip=vcu_cloud_hosting_credentials['ip'],
                                 username=vcu_cloud_hosting_credentials['username'],
                                 password=vcu_cloud_hosting_credentials['password'],
                                 prompt=myprompt,
                                 timeout=timeout,
                                 width=width,
                                 alias=alias,
                                 keyfile=keyfile)
        self.vcu_ssh_conn_store.append(alias)
        return alias

    def disconnect_vcu_cloud_hosting(self, alias='default'):
        """
        disconnect the ssh connection from cu cloud hosting.

        :param str alias: ssh connection alias.
        :return: None
        """
        try:
            self.ssh_conn.disconnect(alias=alias)
            self.vcu_ssh_conn_store.remove(alias)
        except Exception:
            logger.error(
                "{} SSH connection Already disconnected, no need to disconnect it once again {}".format(LOG_HEAD,
                                                                                                        LOG_END))

    def disconnect_all_vcu_cloud_hosting(self):
        self.ssh_conn.disconnect()

    def ssh_connection_to_fhgw(self, gnb_index=0, vdu_index=0, fhgw_index=0, alias='default', timeout=150, width=200, ):
        """
        ssh login to fhgw.

        :param int gnb_index: gnb index in testline init file.
        :param int vdu_index: vdu index in testline init file.
        :param int fhgw_index: fhgw index in testline init file.
        :param str alias: connection alias, default is 'default'.
        :param Union[int,str] timeout: (optional) Timeout for ssh connection setup, default is 150s.
        :param int width: width of ssh window (optional), default is 200.
        :return str: connection alias
        """
        fhgw_credentials = tl_config.get_fhgw_credentials(gnb_index, vdu_index, fhgw_index)
        self.ssh_conn.connect_to(ip=fhgw_credentials['fhgw_ipv4_addr'],
                                 username=fhgw_credentials['fhgw_admin_username'],
                                 password=fhgw_credentials['fhgw_admin_password'],
                                 timeout=timeout,
                                 width=width,
                                 alias=alias)
        self.fhgw_ssh_conn_store.append(alias)
        # TODO: different user has different prompt, maybe this needs to be updated. if ... else ...
        self.ssh_conn.set_prompt(
            '\\[{}@\\S+\\s\\S+\\][\\r\\n]+#'.format(fhgw_credentials['fhgw_admin_username']),
            alias=alias)
        return alias

    def disconnect_fhgw_ssh_conn(self, alias='default'):
        """
        disconnect the ssh connection from fhgw.

        :param str alias: ssh connection alias.
        :return: None
        """
        try:
            self.ssh_conn.disconnect(alias=alias)
            self.fhgw_ssh_conn_store.remove(alias)
        except Exception:
            logger.error(
                "{} SSH connection Already disconnected, no need to disconnect it once again {}".format(LOG_HEAD,
                                                                                                        LOG_END))

    def disconnect_all_fhw_ssh_conn(self):
        self.ssh_conn.disconnect()

    # TODO: get pod and container full name in the keyword;
    #   kubectl exec -it oampm-0 -c oampm -n cran1 -- bash -c "dpdk-cli show port table | grep ${port_name}" | awk '{print $1}'
    def execute_kubectl_exec_cmd(self, pod_name, container_name, command, namespace,
                                 check_result=True, conn_alias='default', exe_bare=False):
        """
        Executing kubectl command in cloud hosting, e.g,::
          kubectl exec -it po-cran1-oampm-0 -c ctr-cran1-oampm -n cran1 -- pwd
        It's common for cu and vdu, so namespace is needed.

        :param str pod_name: full pod name or pod abbr with index, e.g, oamext-0
        :param str container_name: the full container name or abbr.
        :param str command: e.g,
                            bash -c "cd tmp; ls -al",
                            ls -al,
                            bash -c "cd tmp; ls -al"|awk '{print $1}'
        :param str namespace: the namespace.
        :param boolean check_result: checking the command result or or not, default is true.
        :param str conn_alias: the ssh connection alias.
        :param boolean exe_bare: execute bare command or not, default is False.
        :return: the output of the command.
        """
        pod_full_name, container_full_name = self.get_full_pod_and_container_name(pod_abbr=pod_name, container_abbr=container_name,
                                                                                  namespace=namespace, alias=conn_alias)

        base_cmd = 'kubectl exec -it {pod_name} -c {c_name} -n {ns} -- '.format(pod_name=pod_full_name,
                                                                                c_name=container_full_name,
                                                                                ns=namespace)
        cmd = base_cmd + command
        if exe_bare:
            self.ssh_conn.execute_bare(command=cmd, alias=conn_alias)
            self.ssh_conn.execute_bare(command='\r', alias=conn_alias)
        else:
            res = self.ssh_conn.execute(command=cmd, check_result=check_result, alias=conn_alias)
            return generic_utils.strip_prompt_for_cmd_out(content=res, prompt=self.ssh_conn.get_prompt(alias=conn_alias))

    def get_all_pods_name(self, namespace, alias='default'):
        """
        Get vdu pod name list via command kubectl get pods -o wide

        :param str namespace: namespace
        :param str alias: vdu ssh connection alias
        :return: dict pod informaiton: including age, ip, name, node, nominated_node, readiness_gates, ready, restarts, status
        """

        command = 'kubectl get pods -n ' + namespace
        output = self.execute_normal_cmd(base_command=command, alias=alias)
        pods_name_list = []
        lines = output.splitlines()
        lines.pop(0)
        for line in lines:
            pods_name_list.append(line.split()[0].strip())
        return pods_name_list

    def get_specific_pod_container_mapping(self, pod_abbr, namespace, alias='default', container_abbr=None):
        """
        Get vdu pod container mapping via command kubectl get describe pod ...

        :param dict pod_abbr: pod full name, pod abbr with index or pod abbr. e.g. po-cran1-l2rt-0, l2rt-0, l2rt
        :param str namespace: namespace get from testline _init_.py
        :param str alias: vdu ssh connection alias
        :param str container_abbr: container full name, container abbr with index or container abbr. e.g. ctr-cran1-l2rt-0, l2rt-0, l2rt
        :return: dict vdu pod container mapping: {[pod_name: container_1, container_2,...]}
        """
        pods_name_list = self.get_all_pods_name(namespace, alias=alias)
        pod_container_mapping = {}
        for pod in pods_name_list:
            if pod_abbr not in pod:
                continue
            containers = []
            command = (
                'kubectl describe pod ' + pod + ' -n ' + namespace
                + ' | grep -B 1 \'Container ID\' | grep -v \'Container ID\\|--\' | awk \'{print $0}\''
            )
            output = self.execute_normal_cmd(base_command=command, alias=alias)
            for container in output.splitlines():
                ctr_name = container.strip(':').strip()
                if container_abbr is not None:
                    if container_abbr in ctr_name:
                        containers.append(ctr_name)
                else:
                    containers.append(ctr_name)
            pod_container_mapping[pod] = containers
        return pod_container_mapping

    def get_full_pod_and_container_name(self, pod_abbr, namespace, container_abbr=None, alias='default'):
        pod_ctr_mapping = self.get_specific_pod_container_mapping(pod_abbr=pod_abbr, container_abbr=container_abbr,
                                                                  namespace=namespace, alias=alias)
        return get_pod_and_container_name(pod_ctr_mapping, pod_abbr=pod_abbr, ctr_abbr=container_abbr)

    def execute_normal_cmd(self, base_command, namespace=None, pipe_cmd=None, alias='default', check_result=True):
        """
        Executing other command except 'kubectl exec'.

        :param str base_command: the command needs to be executed, e.g,
                                 kubectl get pods
                                 pwd
        :param str namespace: the namespace that the command executed, default is None.
        :param str pipe_cmd: pipe command like '|grep -i xxx'
        :param str alias: ssh connection alias
        :param boolean check_result: checking the command result or or not, default is true.
        :return: the output of the command.
        """
        if namespace:
            command = '{base_cmd} -n {ns} {pipe_cmd}'.format(base_cmd=base_command,
                                                             ns=namespace if namespace else '',
                                                             pipe_cmd=pipe_cmd if pipe_cmd else '')
        else:
            command = '{base_cmd} {pipe_cmd}'.format(base_cmd=base_command,
                                                     pipe_cmd=pipe_cmd if pipe_cmd else '')

        res = self.ssh_conn.execute(command=command, alias=alias, check_result=check_result)
        return generic_utils.strip_prompt_for_cmd_out(res, prompt=self.ssh_conn.get_prompt(alias=alias))

    def download_file(self, remote_path, local_path, alias='default'):
        self.ssh_conn.download_file(remote_path=remote_path, local_path=local_path, alias=alias)

    def connect_to_container(self, pod_name, container_name, namespace='',
                             check_result=True, conn_alias='default'):
        old_prompt = self.ssh_conn.get_prompt(alias=conn_alias)
        container_prompt = old_prompt + '|bash-\\d\\.\\d\\$\\s'
        logger.info('New prompt is {prompt}'.format(prompt=container_prompt))
        self.ssh_conn.set_prompt(prompt_str=container_prompt, alias=conn_alias)
        try:
            self.execute_kubectl_exec_cmd(pod_name=pod_name, container_name=container_name, namespace=namespace,
                                          command='bash', conn_alias=conn_alias, check_result=check_result)
        except RuntimeError as e:
            logger.info(e)
        except Exception as e:
            raise Exception(e)

    def vdu_get_a_remote_directory(self, ns, alias, case_name=None, time_info=None):
        base_folder = '/tmp/tmp_taic_{}'.format(ns)
        self.ssh_conn.execute(command='sudo mkdir -p %s' % base_folder, alias=alias)
        self.ssh_conn.execute(command='sudo chmod -R 777 %s' % base_folder, alias=alias)
        full_path = base_folder
        if case_name:
            full_path = path.join(full_path, case_name)
        if time_info:
            full_path = path.join(full_path, str(time_info))
        self.ssh_conn.execute(command='mkdir -p %s' % full_path, alias=alias)
        self.ssh_conn.execute(command='touch %s' % full_path, alias=alias)
        self.ssh_conn.execute(command='sudo mkdir -p %s' % full_path, alias=alias)
        self.ssh_conn.execute(command='sudo chmod -R 777 %s' % full_path, alias=alias)
        return full_path

    def execute_bare_command(self, command, alias):
        self.ssh_conn.execute_bare(command=command, alias=alias)

    def read_output_until_prompt(self, alias):
        return self.ssh_conn.read_output_until(alias=alias)

    def get_pod_located_node(self, pod_name, namespace, alias):
        """
        get pod located node

        :param str pod_name: the full pod name or the abbreviation of the pod name, e.g. po-cran1-l2rt-1 or l2rt-1
        :param str namespace: the namespace that the command executed, default is None.
        :param str alias: connection alias, default is 'default'.
        :return str: pod node name
        """
        pod_cmd = """kubectl get pod %s -o yaml -n %s|grep nodeName|awk -F ": " '{print $2}'""" % (pod_name,
                                                                                                   namespace)
        node_name = self.ssh_conn.execute(command=pod_cmd, alias=alias)
        node_name = generic_utils.strip_prompt_for_cmd_out(content=node_name,
                                                           prompt=self.ssh_conn.get_prompt(alias=alias))
        return node_name

    def _connect_to_specific_node(self, node_name, alias, gnb_index=0, vdu_index=0):
        password = tl_config.get_vdu_cloud_hosting_credentials(tenant_credentials=False, gnb_index=gnb_index,
                                                               vdu_index=vdu_index)['password']
        connect_cmd = 'ssh -o StrictHostKeyChecking=no %s' % node_name
        old_prompt = self.ssh_conn.get_prompt(alias=alias)
        new_prompt = old_prompt + '|assword:'
        self.ssh_conn.set_prompt(prompt_str=new_prompt, alias=alias)
        out = self.ssh_conn.execute(command=connect_cmd, alias=alias)
        if 'assword:' in out:
            self.ssh_conn.execute(command=password, alias=alias)
        time.sleep(0.5)

    def connect_to_vdu_pod_located_node(self, pod_name, namespace, using_tenant=False, prompt=None, keyfile='',
                                        timeout=150, width=200, alias='default', gnb_index=0, vdu_index=0):
        """
        connect to vdu pod located node.

        :param str pod_name: the full pod name or the abbreviation of the pod name, e.g. po-cran1-l2rt-1 or l2rt-1
        :param str namespace: the namespace that the command executed, default is None.
        :param boolean using_tenant: connect to the cloud hosting by tenant or core
        :param str prompt: the terminal prompt after connected, default is None.
        :param str keyfile: key file path, default is empty.
        :param Union[int,str] timeout: (optional) Timeout for ssh connection setup, default is 150s.
        :param int width: width of ssh window (optional), default is 200.
        :param str alias: connection alias, default is 'default'.
        :param int gnb_index: gnb index in testline init file.
        :param int vdu_index: vdu index in testline init file.
        """
        self.connect_to_vdu_cloud_hosting(using_tenant=using_tenant, prompt=prompt, keyfile=keyfile, timeout=timeout,
                                          width=width, alias=alias, gnb_index=gnb_index, vdu_index=vdu_index)
        pod_full_name, _ = self.get_full_pod_and_container_name(pod_abbr=pod_name, namespace=namespace, alias=alias)
        node_name = self.get_pod_located_node(pod_name=pod_name, namespace=namespace, alias=alias)
        self._connect_to_specific_node(node_name=node_name, alias=alias, gnb_index=gnb_index, vdu_index=vdu_index)
